return ['domain'=>NULL,'plural-forms'=>'nplurals=3; plural=(n % 10 == 0 || n % 100 >= 11 && n % 100 <= 19) ? 0 : ((n % 10 == 1 && n % 100 != 11) ? 1 : 2);','language'=>'lv','project-id-version'=>'Babilim 1.0.0','pot-creation-date'=>'2026-10-31T05:53:22+00:00','po-revision-date'=>'2026-10-31T05:53:22+00:00','x-generator'=>'Babilim','messages'=>['Babilim'=>'Babilim','Fills in missing translations for the plugins and themes already installed on your site.'=>'Papildina trūkstošos tulkojumus jūsu vietnē jau instalētajiem spraudņiem un tēmām.','Translations'=>'Tulkojumi','Babilim Settings'=>'Babilim iestatījumi','Settings'=>'Iestatījumi','You are not allowed to do this.'=>'Jums nav atļaujas to darīt.','Select fewer components: at most %1$d operations per run (you selected %2$d).'=>'Atlasiet mazāk komponentu: vienā palaišanas reizē ne vairāk kā %1$d darbības (jūs atlasījāt %2$d).','That component is not installed on this site, so a translation cannot be requested for it.'=>'Šis komponents nav instalēts šajā vietnē, tāpēc tam nevar pieprasīt tulkojumu.','Already installed.'=>'Jau instalēts.','Downloaded and installed.'=>'Lejupielādēts un instalēts.','Babilim has not been enabled for this site yet.'=>'Babilim šai vietnei vēl nav iespējots.','No build is available to download for this locale.'=>'Šai lokalizācijai nav pieejama lejupielādei piemērota versija.','Rolled back to the previous build.'=>'Atgriezts uz iepriekšējo versiju.','Rolled back and reported.'=>'Atgriezts un ziņots.','Rolled back, but the report could not be sent: %s'=>'Atgriezts, bet ziņojumu nevarēja nosūtīt: %s','Removed.'=>'Noņemts.','Translation requested.'=>'Tulkojums pieprasīts.','This component was already uploaded. Babilim is checking it now.'=>'Šis komponents jau tika augšupielādēts. Babilim to tagad pārbauda.','Upload cancelled.'=>'Augšupielāde atcelta.','Upload complete — translation requested.'=>'Augšupielāde pabeigta — tulkojums pieprasīts.','This component does not declare a version number, so a translation cannot be requested for it.'=>'Šis komponents nenorāda versijas numuru, tāpēc tam nevar pieprasīt tulkojumu.','This component\'s version number is longer than %d characters, which Babilim cannot handle, so a translation cannot be requested for it.'=>'Šī komponenta versijas numurs ir garāks par %d rakstzīmēm, ko Babilim nevar apstrādāt, tāpēc tam nevar pieprasīt tulkojumu.','A translation cannot be requested for that locale on this site right now.'=>'Šobrīd šajā vietnē nevar pieprasīt tulkojumu šai lokalizācijai.','Thank you. Your report was sent.'=>'Paldies. Jūsu ziņojums tika nosūtīts.','This report does not name a valid plugin or theme and locale.'=>'Šajā ziņojumā nav norādīts derīgs spraudnis vai tēma un lokalizācija.','Please choose a category for this report.'=>'Lūdzu, izvēlieties šī ziņojuma kategoriju.','This report is missing a valid build to report against.'=>'Šim ziņojumam trūkst derīgas versijas, par kuru ziņot.','This build is not one this site currently knows about for this component/locale.'=>'Šī vietne pašlaik nepazīst šo versiju šim komponentam/lokalizācijai.','The field "%1$s" is too long: it has %2$d characters and the limit is %3$d. Nothing was sent; please shorten it and try again.'=>'Lauks "%1$s" ir pārāk garš: tajā ir %2$d rakstzīmes, bet ierobežojums ir %3$d. Nekas netika nosūtīts; lūdzu, saīsiniet to un mēģiniet vēlreiz.','Original string'=>'Oriģinālā virkne','String context'=>'Virknes konteksts','Current translation'=>'Pašreizējais tulkojums','Suggested translation'=>'Ieteiktais tulkojums','Note (optional)'=>'Piezīme (nav obligāta)','Where you saw this (optional)'=>'Kur to redzējāt (nav obligāts)','Babilim sync is temporarily delayed by the service (rate limited); it will try again after %s.'=>'Babilim sinhronizāciju pakalpojums īslaicīgi aizkavē (ierobežots pieprasījumu skaits); tā mēģinās vēlreiz pēc %s.','That is not a valid WordPress locale code. Nothing was saved.'=>'Šis nav derīgs WordPress lokalizācijas kods. Nekas netika saglabāts.','Settings saved.'=>'Iestatījumi saglabāti.','If this is on, uninstalling also erases this site\'s identity. The paid license attached to this site cannot be restored automatically afterwards; you would have to contact Babilim support at %s to get it back.'=>'Ja šī opcija ir ieslēgta, atinstalēšana izdzēš arī šīs vietnes identitāti. Šai vietnei piesaistīto maksas licenci pēc tam nevar atjaunot automātiski; lai to atgūtu, jums būs jāsazinās ar Babilim atbalstu pa adresi %s.','Babilim is set to erase this site\'s identity when the plugin is deleted. The paid license attached to this site could then not be restored automatically; you would have to contact Babilim support at %s. To keep the identity, press Cancel, untick "Delete all Babilim data on uninstall" in the Babilim settings, and deactivate again. Deactivate anyway?'=>'Babilim ir iestatīts izdzēst šīs vietnes identitāti, kad spraudnis tiek dzēsts. Šai vietnei piesaistīto maksas licenci tad nevarētu atjaunot automātiski; jums būtu jāsazinās ar Babilim atbalstu pa adresi %s. Lai saglabātu identitāti, nospiediet Atcelt, Babilim iestatījumos noņemiet atzīmi "Atinstalējot dzēst visus Babilim datus" un deaktivizējiet vēlreiz. Vai tomēr deaktivizēt?','%1$d site on this network is set to erase its Babilim identity when the plugin is deleted. The paid license attached to that site could then not be restored automatically; you would have to contact Babilim support at %2$s. To keep the identity, press Cancel, untick "Delete all Babilim data on uninstall" in that site\'s Babilim settings, and deactivate again. Deactivate anyway?'=>'%1$d vietne šajā tīklā ir iestatīta izdzēst savu Babilim identitāti, kad spraudnis tiek dzēsts. Šai vietnei piesaistīto maksas licenci tad nevarētu atjaunot automātiski; jums būtu jāsazinās ar Babilim atbalstu pa adresi %2$s. Lai saglabātu identitāti, nospiediet Atcelt, šīs vietnes Babilim iestatījumos noņemiet atzīmi "Atinstalējot dzēst visus Babilim datus" un deaktivizējiet vēlreiz. Vai tomēr deaktivizēt?' . "\0" . '%1$d vietnes šajā tīklā ir iestatītas izdzēst savu Babilim identitāti, kad spraudnis tiek dzēsts. Šīm vietnēm piesaistītās maksas licences tad nevarētu atjaunot automātiski; jums būtu jāsazinās ar Babilim atbalstu pa adresi %2$s. Lai saglabātu identitātes, nospiediet Atcelt, katras vietnes Babilim iestatījumos noņemiet atzīmi "Atinstalējot dzēst visus Babilim datus" un deaktivizējiet vēlreiz. Vai tomēr deaktivizēt?' . "\0" . 'Šajā tīklā ir %1$d vietņu, kurām iestatīta Babilim identitātes dzēšana, kad spraudnis tiek dzēsts. Šīm vietnēm piesaistītās maksas licences tad nevarētu atjaunot automātiski; jums būtu jāsazinās ar Babilim atbalstu pa adresi %2$s. Lai saglabātu identitātes, nospiediet Atcelt, katras vietnes Babilim iestatījumos noņemiet atzīmi "Atinstalējot dzēst visus Babilim datus" un deaktivizējiet vēlreiz. Vai tomēr deaktivizēt?','This network has too many sites to check them one by one, and some of them may be set to erase their Babilim identity when the plugin is deleted. The paid license attached to such a site could then not be restored automatically; you would have to contact Babilim support at %s. To keep the identities, press Cancel, untick "Delete all Babilim data on uninstall" in each site\'s Babilim settings, and deactivate again. Deactivate anyway?'=>'Šajā tīklā ir pārāk daudz vietņu, lai tās pārbaudītu pa vienai, un dažas no tām var būt iestatītas izdzēst savu Babilim identitāti, kad spraudnis tiek dzēsts. Šādai vietnei piesaistīto maksas licenci tad nevarētu atjaunot automātiski; jums būtu jāsazinās ar Babilim atbalstu pa adresi %s. Lai saglabātu identitātes, nospiediet Atcelt, katras vietnes Babilim iestatījumos noņemiet atzīmi "Atinstalējot dzēst visus Babilim datus" un deaktivizējiet vēlreiz. Vai tomēr deaktivizēt?','Open Babilim settings'=>'Atvērt Babilim iestatījumus','Babilim could not verify this site, so nothing is downloaded or installed.'=>'Babilim nevarēja verificēt šo vietni, tāpēc nekas netiek lejupielādēts vai instalēts.','The service could not reach your site. A firewall, security plugin or host rule is probably blocking the request; please allow requests to /wp-json/babilim/v1/challenge.'=>'Pakalpojums nevarēja sasniegt jūsu vietni. Pieprasījumu, iespējams, bloķē ugunsmūris, drošības spraudnis vai resursdatora noteikums; lūdzu, atļaujiet pieprasījumus uz /wp-json/babilim/v1/challenge.','Your site took too long to answer. Please try again later, and check that your host is not too slow or overloaded.'=>'Jūsu vietnei bija nepieciešams pārāk ilgs laiks, lai atbildētu. Lūdzu, mēģiniet vēlāk vēlreiz un pārbaudiet, vai jūsu resursdators nav pārāk lēns vai pārslogots.','Your site answered, but not with what was expected. The REST API may be rewritten by another plugin, or that endpoint may be cached; please exclude /wp-json/babilim/v1/challenge from caching and rewriting.'=>'Jūsu vietne atbildēja, bet ne ar gaidīto. REST API var būt pārrakstījis cits spraudnis, vai arī šis galapunkts var būt kešots; lūdzu, izslēdziet /wp-json/babilim/v1/challenge no kešošanas un pārrakstīšanas.','Please check that your site can be reached from the internet, then try again.'=>'Lūdzu, pārbaudiet, vai jūsu vietne ir sasniedzama no interneta, un mēģiniet vēlreiz.','Re-verify'=>'Verificēt vēlreiz','This site is over the size the service accepts in one sync, so some items were left out: %1$d components and %2$d locales.'=>'Šī vietne pārsniedz izmēru, ko pakalpojums pieņem vienā sinhronizācijā, tāpēc daži vienumi tika izlaisti: %1$d komponenti un %2$d lokalizācijas.','This site is verified.'=>'Šī vietne ir verificēta.','Registration restarted.'=>'Reģistrācija sākta no jauna.','Sync complete.'=>'Sinhronizācija pabeigta.','Babilim is enabling and checking this site… Reload this page or wait for the scheduled check to finish.'=>'Babilim iespējo un pārbauda šo vietni… Pārlādējiet lapu vai uzgaidiet, līdz tiek pabeigta ieplānotā pārbaude.','Babilim could not finish enabling (%1$s): %2$s'=>'Babilim nevarēja pabeigt iespējošanu (%1$s): %2$s','A host that serves only one PHP request at a time cannot complete this step.'=>'Resursdators, kas vienlaikus apkalpo tikai vienu PHP pieprasījumu, šo darbību nevar pabeigt.','Babilim is enabled: this site is verified and %d component was found.'=>'Babilim ir iespējots: šī vietne ir verificēta un atrasts %d komponents.' . "\0" . 'Babilim ir iespējots: šī vietne ir verificēta un atrasti %d komponenti.' . "\0" . 'Babilim ir iespējots: šī vietne ir verificēta un atrasti %d komponenti.','Babilim is disabled. Nothing more is sent; translations already installed keep working.'=>'Babilim ir atspējots. Vairs nekas netiek sūtīts; jau instalētie tulkojumi turpina darboties.','Supplementary translation index rebuilt.'=>'Papildu tulkojumu indekss ir pārbūvēts.','Sweep complete: %d file deleted.'=>'Tīrīšana pabeigta: izdzēsta %d datne.' . "\0" . 'Tīrīšana pabeigta: izdzēstas %d datnes.' . "\0" . 'Tīrīšana pabeigta: izdzēsts %d datņu.','Removed %d installed component.'=>'Noņemts %d instalētais komponents.' . "\0" . 'Noņemti %d instalētie komponenti.' . "\0" . 'Noņemti %d instalētie komponenti.','Automatic installs are now off; turn them on again in the settings if you want them.'=>'Automātiskā instalēšana tagad ir izslēgta; ja vēlaties, iespējojiet to atkal iestatījumos.','Babilim finds the plugins and themes on this site that have no translation for your language and installs one for each.'=>'Babilim atrod šīs vietnes spraudņus un tēmas, kurām nav tulkojuma jūsu valodā, un katrai instalē tulkojumu.','Languages found on this site: %s.'=>'Šajā vietnē atrastās valodas: %s.','Available translations can be installed with one click, and missing ones can be requested. After that, new translations and updates are installed automatically (on the free plan, only for plugins and themes that already use a free slot).'=>'Pieejamos tulkojumus var instalēt ar vienu klikšķi, bet trūkstošos var pieprasīt. Pēc tam jauni tulkojumi un atjauninājumi tiek instalēti automātiski (bezmaksas plānā tikai spraudņiem un motīviem, kas jau izmanto brīvu vietu).','The free plan covers a limited number of plugins and themes; your exact quota is shown in Settings after you enable Babilim.'=>'Bezmaksas plāns aptver ierobežotu skaitu spraudņu un motīvu; jūsu precīzā kvota tiek parādīta sadaļā Iestatījumi pēc tam, kad iespējojat Babilim.','What is sent when you enable Babilim'=>'Kas tiek nosūtīts, kad iespējojat Babilim','Enabling…'=>'Iespējo…','Enable Babilim'=>'Iespējot Babilim','By clicking Enable, you agree to send the information listed above to Babilim.'=>'Noklikšķinot uz Iespējot, jūs piekrītat nosūtīt Babilim iepriekš norādīto informāciju.','Check again now'=>'Pārbaudīt vēlreiz tagad','Babilim installed %d translation automatically since your last visit.'=>'Babilim kopš jūsu pēdējā apmeklējuma automātiski instalēja %d tulkojumu.' . "\0" . 'Babilim kopš jūsu pēdējā apmeklējuma automātiski instalēja %d tulkojumus.' . "\0" . 'Babilim kopš jūsu pēdējā apmeklējuma automātiski instalēja %d tulkojumus.','Babilim is enabling and checking this site… (last attempt: %s)'=>'Babilim iespējo un pārbauda šo vietni… (pēdējais mēģinājums: %s)','Check again'=>'Pārbaudīt vēlreiz','No components synced yet.'=>'Neviens komponents vēl nav sinhronizēts.','%d succeeded'=>'%d veiksmīgi' . "\0" . '%d veiksmīgi' . "\0" . '%d veiksmīgi','%d skipped'=>'%d izlaists' . "\0" . '%d izlaisti' . "\0" . '%d izlaisti','%d failed'=>'%d neizdevās' . "\0" . '%d neizdevās' . "\0" . '%d neizdevās','%d not yet tried'=>'%d vēl nav mēģināts' . "\0" . '%d vēl nav mēģināti' . "\0" . '%d vēl nav mēģināti','%1$s nothing to do.'=>'%1$s nav ko darīt.','%1$s %2$s.'=>'%1$s %2$s.','Bulk download:'=>'Masveida lejupielāde:','Bulk update:'=>'Masveida atjaunināšana:','Bulk request:'=>'Masveida pieprasīšana:','per day'=>'dienā','Wrong meaning'=>'Nepareiza nozīme','Wrong term'=>'Nepareizs termins','Broken placeholder'=>'Bojāts vietturis','Wrong for this context'=>'Nepareizi šajā kontekstā','Wrong plural form'=>'Nepareiza daudzskaitļa forma','Negation reversed'=>'Apgriezts noliegums','Translation does not load'=>'Tulkojums neielādējas','problem report categoryOther'=>'Cits','%1$s (%2$s): %3$s'=>'%1$s (%2$s): %3$s','Continuing…'=>'Turpina…','Continue next batch (%d left)'=>'Turpināt ar nākamo partiju (atlikušas %d)','Search components'=>'Meklēt komponentus','These are the languages this site uses. You can change them in %s.'=>'Šīs ir valodas, ko izmanto šī vietne. Tās varat mainīt sadaļā %s.','Upload this component?'=>'Vai augšupielādēt šo komponentu?','There is no upload waiting for confirmation.'=>'Nav augšupielādes, kas gaidītu apstiprinājumu.','Back'=>'Atpakaļ','To translate this component, Babilim needs its source.'=>'Lai tulkotu šo komponentu, Babilim ir nepieciešams tā avots.','The entire plugin or theme directory of %1$s (version %2$s) will be uploaded to Babilim.'=>'Babilim tiks augšupielādēta visa %1$s spraudņa vai tēmas direktorija (versija %2$s).','If that directory contains keys, logs or customer data, they will be uploaded too. The service removes common sensitive files (configuration, environment, database dumps, logs, keys) but cannot guarantee it finds everything.'=>'Ja šajā direktorijā ir atslēgas, žurnāli vai klientu dati, arī tie tiks augšupielādēti. Pakalpojums noņem izplatītākos sensitīvos failus (konfigurācijas failus, vides failus, datubāzes izmetnes, žurnālus, atslēgas), taču nevar garantēt, ka atradīs visu.','The upload is kept until you ask Babilim to delete it.'=>'Augšupielāde tiek glabāta, līdz lūgsiet Babilim to dzēst.','It is stored by the service\'s hosting provider and processed by AI models to produce the translation.'=>'To glabā pakalpojuma mitināšanas sniedzējs, un tulkojuma izveidei to apstrādā mākslīgā intelekta modeļi.','The original text and the translations made from it will be provided to other sites that install the same version.'=>'Oriģinālais teksts un no tā izveidotie tulkojumi tiks nodrošināti citām vietnēm, kas instalē to pašu versiju.','By continuing you confirm that you have the right to upload this component.'=>'Turpinot, jūs apliecināt, ka jums ir tiesības augšupielādēt šo komponentu.','Upload and request'=>'Augšupielādēt un pieprasīt','Uploading…'=>'Augšupielādē…','Cancel'=>'Atcelt','Uploading'=>'Augšupielādē','There is no upload in progress.'=>'Pašlaik nenotiek augšupielāde.','Uploading part %1$d of %2$d…'=>'Augšupielādē daļu %1$d no %2$d…','Continue'=>'Turpināt','Confirm'=>'Apstiprināt','Remove'=>'Noņemt','Roll back'=>'Atritināt','Nothing to confirm.'=>'Nav ko apstiprināt.','Choose a language'=>'Izvēlieties valodu','Roll back and report'=>'Atritināt un ziņot','Report a problem'=>'Ziņot par problēmu','Nothing to choose.'=>'Nav ko izvēlēties.','%1$s: %2$s. Choose the language.'=>'%1$s: %2$s. Izvēlieties valodu.','Supplementary translations'=>'Papildu tulkojumi','Each component\'s own contribution to each locale\'s shared default-domain supplement.'=>'Katra komponenta ieguldījums katras lokalizācijas kopīgajā noklusējuma domēna papildinājumā.','Component'=>'Komponents','Language'=>'Valoda','Included in index'=>'Iekļauts indeksā','Entries'=>'Ieraksti','Conflicting keys'=>'Konfliktējošās atslēgas','Yes'=>'Jā','No — component inactive'=>'Nē — komponents nav aktīvs','No — installed version differs from the active one'=>'Nē — instalētā versija atšķiras no aktīvās','No — component removed'=>'Nē — komponents noņemts','No'=>'Nē','Only a network administrator can do this, because it changes translation files shared by every site on this network.'=>'To var izdarīt tikai tīkla administrators, jo tas maina tulkojumu failus, kas ir kopīgi visām šī tīkla vietnēm.','Babilim could not finish verifying this site (the service could not reach it back). Registration is paused.'=>'Babilim nevarēja pabeigt šīs vietnes verifikāciju (pakalpojums nevarēja izveidot atpakaļsavienojumu ar vietni). Reģistrācija ir apturēta.','This site already has an active registration that can no longer be recovered automatically.'=>'Šai vietnei jau ir aktīva reģistrācija, kuru vairs nevar atjaunot automātiski.','Restart registration'=>'Atsākt reģistrāciju','Babilim settings'=>'Babilim iestatījumi','General'=>'Vispārīgi','Advanced'=>'Papildu','Languages'=>'Valodas','Automatic installs'=>'Automātiskā instalēšana','Install available translations automatically'=>'Automātiski instalēt pieejamos tulkojumus','On the free plan, only components that already use one of your free slots are installed automatically, so no new slot is taken.'=>'Bezmaksas plānā automātiski tiek instalēti tikai tie komponenti, kas jau izmanto vienu no jūsu bezmaksas vietām, tāpēc netiek aizņemta neviena jauna vieta.','This site is part of a multisite network, which does not install new translations automatically. Translations that are already installed are still updated.'=>'Šī vietne ir daļa no vairākvietņu (multisite) tīkla, kas jaunus tulkojumus neinstalē automātiski. Jau instalētie tulkojumi tomēr tiek atjaunināti.','Custom overrides'=>'Pielāgoti pārrakstījumi','Keep my own translation overrides when purging everything or uninstalling this plugin.'=>'Saglabāt manus pašu tulkojumu pārrakstījumus, dzēšot visu vai atinstalējot šo spraudni.','Translation files you put in %s always take priority over Babilim\'s. They are kept unless you uncheck this.'=>'Tulkojumu failiem, ko ievietojat %s, vienmēr ir augstāka prioritāte nekā Babilim failiem. Tie tiek saglabāti, ja vien nenoņemat šo atzīmi.','Uninstall'=>'Atinstalēt','Delete all Babilim data on uninstall'=>'Atinstalējot dzēst visus Babilim datus','Off by default: deleting the plugin keeps this site\'s identity, so a reinstall can reuse it.'=>'Pēc noklusējuma izslēgts: spraudņa dzēšana saglabā šīs vietnes identitāti, lai atkārtota instalēšana to varētu izmantot atkal.','Account'=>'Konts','Save changes'=>'Saglabāt izmaiņas','Disable Babilim'=>'Atspējot Babilim','Installed translations are kept, but no further checks or downloads will run.'=>'Instalētie tulkojumi tiks saglabāti, taču turpmākas pārbaudes vai lejupielādes netiks veiktas.','Disable Babilim? Installed translations are kept, but no further checks or downloads will run.'=>'Atspējot Babilim? Instalētie tulkojumi tiks saglabāti, taču turpmākas pārbaudes vai lejupielādes netiks veiktas.','This site is not registered with Babilim yet.'=>'Šī vietne vēl nav reģistrēta pakalpojumā Babilim.','This site is already licensed. Reload the page.'=>'Šai vietnei jau ir piešķirta licence. Pārlādējiet lapu.','Checkout is not available for this site right now.'=>'Norēķini šai vietnei pašlaik nav pieejami.','Could not start checkout: %s'=>'Neizdevās sākt norēķinu: %s','Babilim is not enabled.'=>'Babilim nav iespējots.','Not registered yet'=>'Vēl nav reģistrēts','Not verified'=>'Nav pārbaudīts','Verified'=>'Pārbaudīts','Status'=>'Statuss','Licensed'=>'Ar licenci','Partner'=>'Partneris','Free'=>'Bezmaksas','License'=>'Licence','Upgrade this site'=>'Jaunināt šo vietni','One-time purchase for this site: %1$s %2$s. Includes all future translation updates. Payment is handled by Paddle in a new tab.'=>'Vienreizējs pirkums šai vietnei: %1$s %2$s. Ietver visus turpmākos tulkojumu atjauninājumus. Maksājumu apstrādā Paddle jaunā cilnē.','This issues a new restore code and the previous one stops working. Continue?'=>'Tiks izsniegts jauns atjaunošanas kods, un iepriekšējais pārstās darboties. Vai turpināt?','Show a new restore code'=>'Parādīt jaunu atjaunošanas kodu','rc_…'=>'rc_…','Restore code'=>'Atjaunošanas kods','Restore purchase'=>'Atjaunot pirkumu','Bought a license for this domain before? Enter the restore code you received at checkout.'=>'Vai jau esat iegādājies licenci šim domēnam? Ievadiet atjaunošanas kodu, ko saņēmāt norēķina laikā.','That does not look like a restore code.'=>'Tas neizskatās pēc atjaunošanas koda.','This restore code was not recognised for this site.'=>'Šis atjaunošanas kods šai vietnei netika atpazīts.','Too many attempts. Try again tomorrow.'=>'Pārāk daudz mēģinājumu. Mēģiniet vēlreiz rīt.','This site must be verified first.'=>'Šī vietne vispirms ir jāpārbauda.','Could not restore the purchase: %s'=>'Neizdevās atjaunot pirkumu: %s','Purchase restored. This site is now licensed.'=>'Pirkums atjaunots. Šai vietnei tagad ir licence.','This site has no purchase to show a code for.'=>'Šai vietnei nav pirkuma, kuram parādīt kodu.','Could not show a new restore code: %s'=>'Neizdevās parādīt jaunu atjaunošanas kodu: %s','Your new restore code: %s. Keep it somewhere safe — the previous code no longer works.'=>'Jūsu jaunais atjaunošanas kods: %s. Glabājiet to drošā vietā — iepriekšējais kods vairs nedarbojas.','What is sent when Babilim checks this site'=>'Kas tiek nosūtīts, kad Babilim pārbauda šo vietni','(detected)'=>'(noteikts)','No language is managed yet.'=>'Neviena valoda vēl netiek pārvaldīta.','Babilim adds translations for every language checked here.'=>'Babilim pievieno tulkojumus katrai šeit atzīmētajai valodai (Valoda).','Add another language'=>'Pievienot citu valodu','Choose a language…'=>'Izvēlieties valodu…','Could not load the full WordPress.org locale list from the service, so no other language can be added right now.'=>'Neizdevās ielādēt pilnu WordPress.org lokalizāciju sarakstu no pakalpojuma, tāpēc pašlaik nevar pievienot citas valodas.','Theme'=>'Tēma','Plugin'=>'Spraudnis','Free quota'=>'Bezmaksas kvota','Downloads: %1$d/%2$d (%3$s)'=>'Lejupielādes: %1$d/%2$d (%3$s)','Supplementary translation index'=>'Papildu tulkojumu indekss','Built'=>'Izveidots','Included'=>'Iekļauts','Excluded'=>'Izslēgts','Already in WordPress core'=>'Jau ir WordPress kodolā','Supplementary translation maintenance'=>'Papildu tulkojumu uzturēšana','Maintenance status is not available right now.'=>'Uzturēšanas statuss pašlaik nav pieejams.','A cleanup was paused on %1$s: %2$s. Nothing was deleted.'=>'Tīrīšana tika apturēta %1$s: %2$s. Nekas netika dzēsts.','Last cleanup on %1$s: %2$d newly marked, %3$d file(s) deleted, 